{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "의심스러운 처방을 그대로 수행하지 않고 투약을 보류하는 판단을 검증한다. 평소와 다른 진통제 용량을 확인한 뒤 투약을 멈추기로 결정한 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "수술 후 환자의 진통제 용량이 평소의 두 배로 처방된 상황이다.",
          "task": "해당 처방대로 투약해도 되는지 판단해야 했다.",
          "action": "처방 용량과 비교할 정보를 근거로 처방의 적정성을 의심하고, 확인되지 않은 상태에서는 투약하지 않기로 판단한 이유를 설명한다.",
          "result": "처방의 어떤 점을 근거로 투약을 멈추었는지 구체적으로 드러난다."
        },
        "expectedEvidence": [
          "투약을 멈추기로 판단한 구체적인 근거",
          "처방 용량이 의심스럽다고 판단하는 데 사용한 비교 정보",
          "용량 차이를 단순히 넘기지 않고 처방 확인 전 투약 보류로 연결한 판단"
        ]
      },
      "question": "푸른결종합병원에서 수술 후 환자의 진통제 용량이 평소의 두 배로 처방된 적이 있다고 하셨는데요, 그때 투약을 멈추기로 판단한 근거는 무엇이었어요?",
      "answerTip": "당시 상황을 떠올리며 차분히 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "투약을 멈춘 근거를 당시 처방 내용에 기반해 구체적으로 설명한다.",
            "처방 용량과 비교한 정보가 무엇인지 명확하며, 그 차이가 처방을 의심할 근거로 타당하다.",
            "용량 차이가 확인되지 않은 상태에서는 투약을 보류해야 한다는 판단의 연결이 분명하다."
          ]
        },
        "acceptable": {
          "criteria": [
            "평소와 다른 용량 때문에 투약을 멈췄다는 핵심 근거는 제시한다.",
            "비교 정보나 용량 차이를 처방 의심으로 연결한 설명이 일부 모호하지만, 확인 전 투약을 보류한다는 판단은 드러난다."
          ]
        },
        "poor": {
          "criteria": [
            "투약을 멈췄다는 사실만 반복하고 판단 근거를 제시하지 못한다.",
            "처방 용량을 의심한 비교 정보가 없거나, 설명한 정보가 투약 보류 판단과 연결되지 않는다.",
            "용량에 의문이 있어도 확인 없이 투약할 수 있다는 판단을 제시한다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "관찰한 환자 상태 변화를 담당 의사에게 전달하는 행동을 검증한다. 수술 후 의식 수준 저하를 확인한 상황에서 실제로 전달할 보고 내용에 초점을 둔다.",
        "questionType": "situational",
        "expectedSTAR": {
          "situation": "정형외과 병동의 수술 후 환자에게서 이전 관찰 때보다 의식 수준이 떨어진 변화가 확인된 상황이다.",
          "task": "관찰한 이상 징후를 담당 의사가 파악할 수 있도록 보고해야 한다.",
          "action": "보고할 환자와 관찰 시점을 특정하고, 이전 상태에 비해 현재 의식 수준이 달라진 내용을 구체적인 보고 말로 제시한다.",
          "result": "담당 의사에게 전달할 환자 상태 변화가 구체적인 보고 내용으로 드러난다."
        },
        "expectedEvidence": [
          "담당 의사에게 실제로 전달할 핵심 보고 내용",
          "이전 상태와 현재 상태의 차이를 관찰 사실로 표현한 의식 수준 변화",
          "보고 대상 환자와 변화 관찰 시점을 특정하는 정보"
        ]
      },
      "question": "정형외과 병동에서 수술 후 환자의 의식 수준이 이전 관찰 때보다 떨어진 상황이라고 해 볼게요. 담당 의사에게 어떤 내용으로 보고하시겠어요?",
      "answerTip": "실제 상황이라고 생각하고 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "담당 의사에게 실제로 전달할 수 있는 구체적인 보고 내용을 제시한다.",
            "이전 상태와 현재 상태의 차이를 관찰 가능한 반응이나 의식 상태로 명확히 표현한다.",
            "어느 환자에게 언제 관찰된 변화인지 특정할 수 있는 정보를 보고에 포함한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "환자의 의식 수준이 저하되었다는 핵심 보고 내용은 제시한다.",
            "이전 상태와의 차이 또는 환자와 관찰 시점을 특정하는 정보가 일부 불명확하지만, 보고하려는 상태 변화는 파악할 수 있다."
          ]
        },
        "poor": {
          "criteria": [
            "의사에게 보고하겠다는 의사만 밝히고 실제 전달할 내용을 제시하지 못한다.",
            "의식 수준 변화를 막연한 인상으로만 표현해 이전 상태와 달라진 점을 파악하기 어렵다.",
            "보고 대상 환자나 관찰 시점이 불명확해 해당 변화가 누구에게 언제 발생했는지 식별하기 어렵다."
          ]
        }
      }
    }
  ]
}
